{
  "items": [
    {
      "name": "Finset.inf'_lt_iff",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {ι : Type u_5} [inst : LinearOrder α] {s : Finset ι} (H : s.Nonempty) {f : ι → α} {a : α},\n  s.inf' H f < a ↔ ∃ i ∈ s, f i < a"
    },
    {
      "name": "Finset.inf_le_iff",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {ι : Type u_5} [inst : LinearOrder α] [inst_1 : OrderTop α] {s : Finset ι} {f : ι → α} {a : α},\n  a < ⊤ → (s.inf f ≤ a ↔ ∃ b ∈ s, f b ≤ a)"
    },
    {
      "name": "Finset.inf'_le_iff",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {ι : Type u_5} [inst : LinearOrder α] {s : Finset ι} (H : s.Nonempty) {f : ι → α} {a : α},\n  s.inf' H f ≤ a ↔ ∃ i ∈ s, f i ≤ a"
    },
    {
      "name": "iInf_lt_iff",
      "module_name": "Mathlib.Order.CompleteLattice.Defs",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ι : Sort u_4} [inst : CompleteLinearOrder α] {a : α} {f : ι → α}, iInf f < a ↔ ∃ i, f i < a"
    },
    {
      "name": "ciInf_lt_iff",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Indexed",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ι : Sort u_4} [inst : ConditionallyCompleteLinearOrder α] {a : α} [Nonempty ι] {f : ι → α},\n  BddBelow (Set.range f) → (iInf f < a ↔ ∃ i, f i < a)"
    },
    {
      "name": "Finset.le_inf'_iff",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {β : Type u_3} [inst : SemilatticeInf α] {s : Finset β} (H : s.Nonempty) (f : β → α) {a : α},\n  a ≤ s.inf' H f ↔ ∀ b ∈ s, a ≤ f b"
    },
    {
      "name": "Finset.inf'_le",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {β : Type u_3} [inst : SemilatticeInf α] {s : Finset β} (f : β → α) {b : β} (h : b ∈ s),\n  s.inf' ⋯ f ≤ f b"
    },
    {
      "name": "Finset.inf_lt_iff",
      "module_name": "Mathlib.Data.Finset.Lattice.Fold",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} {ι : Type u_5} [inst : LinearOrder α] [inst_1 : OrderTop α] {s : Finset ι} {f : ι → α} {a : α},\n  s.inf f < a ↔ ∃ b ∈ s, f b < a"
    }
  ]
}
